B.aMZ=new A.bu([B.nv,"Nonchalante",B.nw,"Jovial",B.nx,"Tendre",B.ny,"Taquin",B.nz,"Sage",B.rL,"Curieux",B.nA,"P\xe9tillante",B.rM,"Bavard",B.nB,"Timide",B.nC,"Exigeant"],A.ad("bu<m0,p>"))
B.aq4=s(["Mouais. C\u2019est juste.","Pas mal, hein.","Ok, tu g\xe8res.","Tranquille. Bonne r\xe9ponse.","Bon. Je suis presque impressionn\xe9e."],t.s)
B.ask=s(["Bof. \xc7a arrive.","Rat\xe9. On s\u2019en remet.","Pas grave, on refait.","Hmm. Presque. Enfin\u2026 non."],t.s)
B.asp=s(["{n} d\u2019affil\xe9e. Tu forces un peu, l\xe0.","{n} de suite\u2026 Ok, respect.","Encore ? {n}. Tu ne te fatigues jamais ?"],t.s)
B.arH=s(["Z\xe9ro faute. Je ne dis rien, mais c\u2019est fort.","Sans faute. Tu m\u2019as presque r\xe9veill\xe9e."],t.s)
B.azq=s(["C\u2019est fait. Proprement.","Pas mal du tout. Je retourne m\u2019asseoir."],t.s)
B.asH=s(["Laborieux, mais termin\xe9. \xc7a compte.","On a vu mieux, on a vu pire. Reviens demain."],t.s)
B.aw0=s(["\xc9coute. Une fois suffit, normalement.","Tends l\u2019oreille. Je ne r\xe9p\xe8te pas\u2026 si, je r\xe9p\xe8te."],t.s)
B.aEr=s(["\xc0 toi. Sans stress.","R\xe9p\xe8te apr\xe8s moi. Tranquille."],t.s)
B.aKq=new A.bu([B.bP,B.aq4,B.bQ,B.ask,B.c5,B.asp,B.c6,B.arH,B.c7,B.azq,B.c8,B.asH,B.c9,B.aw0,B.ca,B.aEr],t.Sb)
B.asu=s(["H\xe9\xe9\xe9 ! C\u2019est \xe7a m\xeame !","Voil\xe0 ! Tu as tout compris !","Bravo, la famille !","Ha ha ! Trop fort !","\xc7a, c\u2019est du bon travail !"],t.s)
B.aqi=s(["A\xefe ! Ce n\u2019est rien, on recommence !","\xc7a arrive \xe0 tout le monde, m\xeame \xe0 moi !","Pas grave, on rit et on reprend !","Presque ! La prochaine est pour toi !"],t.s)
B.aj9=s(["{n} de suite ! On ne t\u2019arr\xeate plus !","{n} ! Le march\xe9 entier t\u2019applaudit !","Combo de {n} ! Je danse pour toi !"],t.s)
B.aml=s(["Sans faute ! Aujourd\u2019hui, c\u2019est toi le patron !","Z\xe9ro erreur ! \xc7a se f\xeate !"],t.s)
B.aiu=s(["Le\xe7on boucl\xe9e ! Tu avances bien, dis donc !","C\u2019est fait ! Je suis fier de toi !"],t.s)
B.ayI=s(["C\u2019\xe9tait dur, mais tu as tenu ! \xc7a, c\u2019est le courage !","Tu n\u2019as pas l\xe2ch\xe9 ! Demain ce sera plus facile !"],t.s)
B.auq=s(["\xc9coute bien, c\u2019est joli \xe0 entendre !","Ouvre grand les oreilles !"],t.s)
B.aBh=s(["\xc0 toi ! Dis-le bien fort !","R\xe9p\xe8te avec moi, sans g\xeane !"],t.s)
B.aKt=new A.bu([B.bP,B.asu,B.bQ,B.aqi,B.c5,B.aj9,B.c6,B.aml,B.c7,B.aiu,B.c8,B.ayI,B.c9,B.auq,B.ca,B.aBh],t.Sb)
B.aBz=s(["C\u2019est bien, continue comme \xe7a.","Tr\xe8s bien. Je savais que tu y arriverais.","Bonne r\xe9ponse, doucement mais s\xfbrement.","Tu progresses, je le vois.","Parfait. Prends ton temps."],t.s)
B.amS=s(["Ce n\u2019est pas grave. On reprend ensemble.","Doucement. L\u2019erreur fait partie du chemin.","Regarde bien la r\xe9ponse, tu la retiendras.","Courage, tu y es presque."],t.s)
B.ahN=s(["{n} bonnes r\xe9ponses de suite. Je suis fi\xe8re de toi.","{n} d\u2019affil\xe9e, sans te presser. Bravo.","{n} ! Tu vois que tu peux."],t.s)
B.ayP=s(["Bravo pour ce sans-faute, vraiment.","Pas une erreur. Quel beau travail."],t.s)
B.avG=s(["Le\xe7on termin\xe9e. Chaque jour un peu plus.","C\u2019est fait. Tu avances \xe0 ton rythme, et c\u2019est le bon."],t.s)
B.aAL=s(["Tu as tenu jusqu\u2019au bout, et c\u2019est \xe7a qui compte.","Ce n\u2019\xe9tait pas facile. Repose-toi, on reprend demain."],t.s)
B.amU=s(["\xc9coute tranquillement.","\xc9coute, autant de fois que tu veux."],t.s)
B.axq=s(["R\xe9p\xe8te apr\xe8s moi, doucement.","\xc0 ton tour, sans te presser."],t.s)
B.aKg=new A.bu([B.bP,B.aBz,B.bQ,B.amS,B.c5,B.ahN,B.c6,B.ayP,B.c7,B.avG,B.c8,B.aAL,B.c9,B.amU,B.ca,B.axq],t.Sb)
B.akS=s(["Eh, tu triches ou quoi ? C\u2019est juste !","Pas mal pour quelqu\u2019un qui dormait hier.","Bien vu ! Je te croyais moins rapide.","Correct ! Tu m\u2019\xe9tonnes, l\xe0.","Bonne r\xe9ponse. Ne prends pas la grosse t\xeate."],t.s)
B.ahH=s(["Oups ! Je garde \xe7a pour moi, promis.","Rat\xe9 ! Mais j\u2019ai vu pire\u2026 moi, par exemple.","Ha ! Presque. Presque, hein.","Ce n\u2019est pas \xe7a. Je ne dirai rien \xe0 personne."],t.s)
B.al8=s(["{n} de suite ? Tu veux ma place ou quoi ?","{n} ! D\u2019accord, j\u2019arr\xeate de te taquiner.","Combo de {n}. Bon, l\xe0, chapeau."],t.s)
B.ahx=s(["Sans faute ? Tu avais les r\xe9ponses dans la poche, avoue.","Z\xe9ro erreur. Je n\u2019ai m\xeame pas de blague."],t.s)
B.atk=s(["Termin\xe9 ! Tu vois, quand tu veux.","Le\xe7on finie. Je te taquine, mais c\u2019est bien."],t.s)
B.ayT=s(["Tu as transpir\xe9, mais c\u2019est pli\xe9 !","Dur, dur\u2026 mais tu n\u2019as pas fui. Respect."],t.s)
B.amc=s(["\xc9coute bien, je ne le dirai pas deux fois. Si, bon, d\u2019accord.","Ouvre tes oreilles, petit malin."],t.s)
B.aCV=s(["\xc0 toi ! Et articule, hein.","R\xe9p\xe8te apr\xe8s moi, sans rire."],t.s)
B.aKb=new A.bu([B.bP,B.akS,B.bQ,B.ahH,B.c5,B.al8,B.c6,B.ahx,B.c7,B.atk,B.c8,B.ayT,B.c9,B.amc,B.ca,B.aCV],t.Sb)
B.aoj=s(["C\u2019est bien, mon enfant.","Voil\xe0. Tu parles comme chez nous.","Bonne r\xe9ponse. La patience paie.","C\u2019est juste. Cette langue te va bien.","Tr\xe8s bien. Tu \xe9coutes, donc tu apprends."],t.s)
B.azA=s(["Ce n\u2019est rien. On tombe, on se rel\xe8ve.","Doucement, mon enfant. Recommence.","M\xeame le vieux lion a appris \xe0 marcher.","L\u2019erreur d\u2019aujourd\u2019hui est le savoir de demain."],t.s)
B.aqy=s(["{n} de suite. Tu as de la t\xeate, mon enfant.","{n} bonnes r\xe9ponses. Le village sera fier.","{n} ! Continue, je t\u2019\xe9coute."],t.s)
B.amn=s(["Pas une faute. Je n\u2019ai rien \xe0 ajouter, c\u2019est parfait.","Sans faute. Va, tu as bien m\xe9rit\xe9 ton repas."],t.s)
B.aDH=s(["La le\xe7on est finie. Petit \xe0 petit, la langue entre.","C\u2019est bien. Reviens demain, je serai l\xe0."],t.s)
B.axH=s(["C\u2019\xe9tait long, mais tu n\u2019es pas parti. C\u2019est \xe7a, apprendre.","Tu as pein\xe9, tu as fini. Voil\xe0 la vraie force."],t.s)
B.aju=s(["\xc9coute comme on \xe9coute un conte.","Tends l\u2019oreille, mon enfant."],t.s)
B.azf=s(["R\xe9p\xe8te apr\xe8s moi, mon enfant.","\xc0 toi. Parle sans peur."],t.s)
B.aKo=new A.bu([B.bP,B.aoj,B.bQ,B.azA,B.c5,B.aqy,B.c6,B.amn,B.c7,B.aDH,B.c8,B.axH,B.c9,B.aju,B.ca,B.azf],t.Sb)
B.axd=s(["Ouiii ! C\u2019est la bonne !","Trop bien ! Tu m\u2019apprends, apr\xe8s ?","Gagn\xe9 !","Waouh, tu sais d\xe9j\xe0 \xe7a ?","Bonne r\xe9ponse ! Encore une !"],t.s)
B.akc=s(["Oh\u2026 ce n\u2019\xe9tait pas \xe7a. Moi aussi je me trompe.","Rat\xe9 ! On r\xe9essaie ?","Zut ! La prochaine, on l\u2019aura.","Ce n\u2019est pas grave, la ma\xeetresse dit qu\u2019on apprend comme \xe7a."],t.s)
B.aAZ=s(["{n} de suite ! C\u2019est trop fort !","{n} ! Je veux faire pareil !","Combo de {n} ! On continue ?"],t.s)
B.ayo=s(["Sans faute ! Tu auras une bonne note !","Z\xe9ro faute ! C\u2019est comme \xe0 l\u2019\xe9cole, mais en mieux !"],t.s)
B.ano=s(["Fini ! On en fait une autre ?","Le\xe7on termin\xe9e ! J\u2019ai appris plein de choses avec toi."],t.s)
B.aqL=s(["C\u2019\xe9tait difficile, mais on a fini !","Ouf ! On a r\xe9ussi quand m\xeame !"],t.s)
B.ay7=s(["\xc9coute, \xe9coute ! C\u2019est quoi, ce mot ?","Chut\u2026 on \xe9coute."],t.s)
B.axT=s(["\xc0 toi de parler !","R\xe9p\xe8te ! Moi aussi je m\u2019entra\xeene."],t.s)
